Use a 17-slot circular buffer with an explicit element count, so none of the slots need to be reserved. The invariant is that `size_` stays between 0 and 17, and the next insertion index is `(head_ + size_) % 17`; empty means `size_ == 0`, while full means `size_ == 17`. A rejected push or failed pop leaves the queue unchanged; compile and run with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo && ./fifo`, without `-DNDEBUG` so the assertions execute.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) {
            return false;
        }
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    bool pop(int& value) {
        if (size_ == 0) {
            return false;
        }
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return true;
    }

    std::size_t size() const noexcept { return size_; }
    bool empty() const noexcept { return size_ == 0; }
    bool full() const noexcept { return size_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -1;

    // Empty pop fails and leaves its output unchanged.
    assert(queue.empty());
    assert(!queue.pop(value));
    assert(value == -1);

    // All 17 slots are usable.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }
    assert(queue.full());

    // The 18th insertion is rejected. Draining verifies that
    // rejection changed neither the size nor the queued contents.
    assert(!queue.push(999));
    assert(queue.size() == 17);
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    // Move the head forward while keeping elements queued, then
    // refill across the physical end of the array.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(100 + i));
    }
    for (int i = 0; i < 10; ++i) {
        assert(queue.pop(value));
        assert(value == 100 + i);
    }
    assert(queue.size() == 7);
    for (int i = 0; i < 10; ++i) {
        assert(queue.push(117 + i));
    }
    assert(queue.full());
    assert(!queue.push(999));
    for (int expected = 110; expected <= 126; ++expected) {
        assert(queue.pop(value));
        assert(value == expected);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    std::cout << "All FIFO tests passed.\n";
}
```

The lower median is 4: sorting a copy of [9,1,4,4,7,2] gives [1,2,4,4,7,9], and the lower middle element is at zero-based index 2. The function copies the caller’s array, rejects empty input, and uses `std::nth_element` to select index `(n - 1) / 2` without sorting the entire copy.

For odd size `n = 2m + 1`, that index is `m`, with exactly `m` sorted positions on either side. For even size `n = 2m`, it is `m - 1`, the lower of the two middle indices `m - 1` and `m`. `std::nth_element` places the same value at that index as a full sort would, including when values are duplicated.

Compile and run with `g++ -std=c++17 -Wall -Wextra -pedantic median.cpp -o median && ./median`, without `-DNDEBUG` so the assertions execute.

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

int lower_median(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }

    std::vector<int> copy = input;
    const std::size_t index = (copy.size() - 1) / 2;
    auto selected = copy.begin() +
        static_cast<std::vector<int>::difference_type>(index);
    std::nth_element(copy.begin(), selected, copy.end());
    return *selected;
}

int main() {
    const auto check = [](const std::vector<int>& input, int expected) {
        const std::vector<int> original = input;
        const int result = lower_median(input);
        assert(result == expected);
        assert(input == original); // Caller contents and order are unchanged.
    };

    check({9, 1, 4, 4, 7, 2}, 4); // Requested example and duplicates.
    check({2, 2, 2, 2}, 2);        // All duplicates.
    check({9, 1, 7, 3, 5}, 5);     // Odd size: sorted middle index 2.
    check({8, 2, 6, 4}, 4);        // Even size: lower middle, not 6.
    check({42}, 42);                // Singleton: index 0.

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lower_median(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());

    std::cout << "All lower-median tests passed.\n";
}
```

No. If `desired` is computed only once, a failed compare-exchange can update `expected` while leaving `desired` stale, so a later successful retry may not increment anything.

Here is a concrete execution with the counter initially 0:
1. Thread A loads `expected = 0` and computes `desired = 1`.
2. Thread B successfully increments the counter from 0 to 1 and returns.
3. Thread A attempts compare-exchange with expected 0 and desired 1. It fails because the counter is 1, and overwrites A’s `expected` with 1; A’s `desired` remains 1.
4. Thread A retries with expected 1 and desired 1. This succeeds, storing 1 again, and A returns. Two increment calls have completed, but the counter is only 1 instead of 2.

The fix is to recompute `desired = expected + 1` before every attempt. A spurious failure also returns to that recomputation step: failure never counts as an increment, even if `expected` remains unchanged. Relaxed ordering suffices for this standalone counter; the thread joins ensure the final check happens after all increments finish. This unsigned counter uses modulo arithmetic on overflow, and the test stays well below that limit.

Compile and run with `g++ -std=c++17 -O2 -Wall -Wextra -pedantic -pthread counter.cpp -o counter && ./counter`, without `-DNDEBUG` so the assertion executes.

```cpp
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

void increment(std::atomic<std::uint64_t>& counter) {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const std::uint64_t desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // On failure, expected receives the observed value.
        // Recompute desired on every retry, including spurious failures.
    }
}

int main() {
    constexpr unsigned thread_count = 8;
    constexpr std::uint64_t increments_per_thread = 100000;
    constexpr std::uint64_t expected_total =
        thread_count * increments_per_thread;

    std::atomic<std::uint64_t> counter{0};
    std::vector<std::thread> workers;
    workers.reserve(thread_count);

    for (unsigned t = 0; t < thread_count; ++t) {
        workers.emplace_back([&counter] {
            for (std::uint64_t i = 0; i < increments_per_thread; ++i) {
                increment(counter);
            }
        });
    }
    for (auto& worker : workers) {
        worker.join();
    }

    const std::uint64_t actual = counter.load(std::memory_order_relaxed);
    assert(actual == expected_total);
    std::cout << "Final count: " << actual << " (test passed)\n";
}
